import{_ as o,o as t,c as a,a5 as i}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"3.2.3 Sign In With Google OAuth","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-3-sign-in-with-google-oauth/spec.md","filePath":"feature/authentication/3-2-3-sign-in-with-google-oauth/spec.md"}'),c={name:"feature/authentication/3-2-3-sign-in-with-google-oauth/spec.md"};function n(r,e,d,s,l,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="_3-2-3-sign-in-with-google-oauth" tabindex="-1">3.2.3 Sign In With Google OAuth <a class="header-anchor" href="#_3-2-3-sign-in-with-google-oauth" aria-label="Permalink to &quot;3.2.3 Sign In With Google OAuth&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.2.3</td></tr><tr><td>Feature</td><td>Sign In with Google OAuth</td></tr><tr><td>Domain</td><td>Authentication (FR 3.2)</td></tr><tr><td>Role</td><td>Guest (unauthenticated)</td></tr><tr><td>Endpoints</td><td><code>GET /api/v1/auth/oauth/google</code> (authorize redirect), <code>GET /api/v1/auth/oauth/google/callback</code> and alias <code>GET /login/oauth2/code/google</code> (Google callback) — both in <code>GoogleOAuthController</code></td></tr><tr><td>Document status</td><td>Implemented — v1.1, 2026-09-25: <code>GoogleOAuthController.businessFailure()</code> now redirects <code>ACCOUNT_SUSPENDED</code> distinctly (<code>/oauth-callback?error=ACCOUNT_SUSPENDED</code>) instead of the generic <code>oauth_failed</code>; frontend shows a dedicated toast via <code>auth.login.oauthAccountSuspended</code>.</td></tr></tbody></table><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when a Guest activates the &quot;Sign in with Google&quot; button on the sign-in or registration screen, which sends the browser to <code>GET /api/v1/auth/oauth/google</code>.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> GUEST. The same handshake also serves a signed-in user linking Google to their existing account via <code>GET /api/v1/auth/oauth/google/link?token=...</code>, which is outside this feature (see Settings/Account Linking).</li><li><strong>Purpose:</strong> Let a user sign in with an existing Google account, create a local account on first use, and honour two-factor authentication when it is enabled.</li><li><strong>Interface:</strong> A &quot;Sign in with Google&quot; button on both the sign-in and the registration screen. The flow is a redirect handshake: the browser leaves the application for Google&#39;s consent screen and returns to the application&#39;s callback route, which then 302-redirects the browser back to the frontend carrying the result.</li><li><strong>Data Processing:</strong> <code>GoogleOAuthController.redirect()</code> calls <code>GoogleOAuthService.buildAuthorizationUrl()</code> (defined in the shared <code>OAuthService</code> base class) to issue and store a single-use state value, then 302s to Google. <code>GoogleOAuthController.callback()</code> receives Google&#39;s redirect, and <code>OAuthService.handleCallback()</code> validates the state, exchanges the authorization code for a Google access token, fetches the Google profile (<code>GoogleOAuthService.fetchProfile()</code>), links the Google identity to an existing account or creates a new verified one, checks the account status, and then issues tokens or a two-factor challenge. Any <code>BusinessException</code> thrown along the way is routed through <code>GoogleOAuthController.businessFailure()</code>, which now redirects <code>ACCOUNT_SUSPENDED</code> to <code>{frontendUrl}/oauth-callback?error=ACCOUNT_SUSPENDED</code> (distinct from the generic failure redirect), while <code>OAUTH_EMAIL_MISMATCH</code>/<code>OAUTH_ALREADY_LINKED</code> (link-mode only) still go to <code>/settings?error=&lt;code&gt;</code> and every other error still falls through to the generic <code>loginFailure()</code> (<code>?error=oauth_failed</code>).</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Google sign-in entry and return:</p><ul><li>Entry: &quot;Sign in with Google&quot; button on <code>/login</code> and <code>/register</code>, linking to <code>GET /api/v1/auth/oauth/google</code>.</li><li>Return: the browser lands on <code>/oauth-callback</code> (<code>OAuthCallbackPage.tsx</code>). <code>useOAuthCallback()</code> reads <code>token</code> from the URL fragment (or query, as a fallback), clears the URL, stores the token, calls <code>GET /api/v1/auth/me</code> (via <code>authService.getProfile()</code>) to load the profile, then navigates to the pending redirect target or <code>/dashboard</code>; toast MSG11 on success.</li><li>If the callback carries <code>error=ACCOUNT_SUSPENDED</code> in the query string, <code>resolveCallback()</code> throws before the generic-error check and the page shows a dedicated toast via i18n key <code>auth.login.oauthAccountSuspended</code> (&quot;This account has been suspended. Please contact support.&quot; / vi: &quot;Tài khoản này đã bị tạm khóa. Vui lòng liên hệ hỗ trợ.&quot;) and navigates to <code>/login</code>.</li><li>If the callback carries any other <code>error</code> in the query string, or no token is present, the page clears any partial auth state, shows toast MSG12 (<code>auth.login.oauthFailed</code>) or the equivalent <code>auth.login.oauthProfileFailed</code> (if the profile call itself fails after a token was received), and navigates to <code>/login</code>.</li><li>When two-factor authentication is enabled the browser lands on the two-factor code screen (3.2.7) instead, carrying <code>twoFactorToken</code> as a query parameter.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> nothing entered by the user; Google supplies <code>code</code> and <code>state</code> (or <code>error</code>) on the callback via <code>GoogleOAuthCallbackRequest(code, state, error)</code>.</li><li><strong>Input optional:</strong> none.</li><li><strong>System data:</strong> <code>providerId</code> (Google <code>id</code>), <code>email</code>, <code>emailVerifiedAt</code>, <code>passwordHash</code> (absent for OAuth-only users), <code>twoFactorEnabled</code>, <code>status</code>/<code>isActive</code>, <code>lastLoginAt</code>, active <code>workspaceId</code>, <code>accessToken</code>, <code>refreshToken</code>, <code>twoFactorToken</code>.</li><li><strong>Output:</strong> on success, a <code>302</code> redirect to <code>{frontendUrl}/oauth-callback#token={accessToken}</code> (fragment, never a query parameter) plus a <code>Set-Cookie: refreshToken=...; HttpOnly; Secure; Path=/api/v1/auth; SameSite=Strict</code>. When two-factor authentication is enabled, a <code>302</code> redirect to <code>{frontendUrl}/2fa-verify?twoFactorToken=...</code> is returned instead and no cookie is set. On a suspended/inactive account, a <code>302</code> redirect to <code>{frontendUrl}/oauth-callback?error=ACCOUNT_SUSPENDED</code>. On any other failure, a <code>302</code> redirect to <code>{frontendUrl}/oauth-callback?error=oauth_failed</code>, except the two account-linking conflicts below which redirect to <code>{frontendUrl}/settings?error=OAUTH_EMAIL_MISMATCH</code> / <code>?error=OAUTH_ALREADY_LINKED</code> (link-mode only — see Out of Scope).</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-09:</strong> The state value is single-use, stored in Redis under <code>oauth:state:{state}</code> for 10 minutes and deleted on first read via <code>getAndDelete</code> (CSRF protection). A missing/expired/unknown state, or a state recorded for a different provider → 400 <code>OAUTH_STATE_INVALID</code>, and the browser is returned to the sign-in screen with a generic error (Toast MSG12).</li><li><strong>BR-10:</strong> Email is the linking anchor for OAuth — <code>linkOrCreateUser()</code> looks up an existing account by lower-cased/trimmed email; a match reuses that account and links the Google identity to it (no duplicate account); no match creates a new account. A failed token exchange, or a Google profile without an <code>id</code>/<code>email</code>, or with <code>verified_email != true</code> → 400 <code>OAUTH_CODE_INVALID</code>, browser returned with a generic error (Toast MSG12).</li><li><strong>BR-11:</strong> <code>UserOAuthProviderRepository.findByProviderAndProviderId(provider, providerId)</code> enforces one <code>(provider, providerId)</code> pair → exactly one user. On first use of a Google identity the local account is created with <code>emailVerifiedAt = now</code>, no <code>passwordHash</code> (set later via <code>/set-password</code>), and default <code>SystemRole.USER</code>.</li><li><strong>BR-06:</strong> <code>!user.isActive() || user.getStatus() != ACTIVE</code> → 403 <code>ACCOUNT_SUSPENDED</code>. <code>GoogleOAuthController.businessFailure()</code> redirects this case distinctly to <code>{frontendUrl}/oauth-callback?error=ACCOUNT_SUSPENDED</code> (not the generic <code>oauth_failed</code>); the frontend shows a dedicated toast (i18n key <code>auth.login.oauthAccountSuspended</code>), separate from the generic OAuth-failure MSG12 toast.</li><li><strong>BR-08:</strong> When <code>user.isTwoFactorEnabled()</code>, no access token and no refresh token are issued; a <code>twoFactorToken</code> is generated (<code>jwtUtil.generateTwoFactorToken</code>) and returned instead so the user completes Two-Factor Authentication (3.2.7). Applies uniformly across sign-in methods, including Google.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>The user cancels consent or Google returns an error → <code>GoogleOAuthCallbackRequest.hasAuthorizationCode()</code> is false (missing/blank <code>code</code> or <code>state</code>, or <code>error</code> present) → the browser is sent back to <code>{frontendUrl}/oauth-callback?error=oauth_failed</code> with a generic error (Toast MSG12), without any further call to Google.</li><li>The Google profile has no <code>id</code>/<code>email</code>, or <code>verified_email</code> is not <code>true</code> → rejected with 400 <code>OAUTH_CODE_INVALID</code> (Toast MSG12).</li><li>A <code>RestClientException</code> while calling Google (token exchange or userinfo) is caught, logged with only the exception type (never the request/response body, which can carry OAuth credentials), and treated as a generic login failure (Toast MSG12).</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>The Guest activates &quot;Sign in with Google&quot; on <code>/login</code> or <code>/register</code>, hitting <code>GET /api/v1/auth/oauth/google</code>.</li><li><code>GoogleOAuthController.redirect()</code> calls <code>buildAuthorizationUrl()</code>: a random 24-byte hex state is generated, stored in Redis (<code>oauth:state:{state}</code> → <code>&quot;GOOGLE|&quot;</code>) for 10 minutes, and the browser is 302&#39;d to Google&#39;s consent screen (<code>accounts.google.com/o/oauth2/v2/auth</code>) with <code>client_id</code>, <code>redirect_uri</code>, <code>scope=openid email profile</code>, and <code>state</code>.</li><li>The user authenticates with Google and grants consent.</li><li>Google 302s the browser to <code>/api/v1/auth/oauth/google/callback</code> (or the Spring Security alias <code>/login/oauth2/code/google</code>) with <code>code</code> and <code>state</code>.</li><li><code>GoogleOAuthController.callback()</code> validates <code>hasAuthorizationCode()</code>, then <code>OAuthService.handleCallback(code, state)</code> consumes the state (BR-09), exchanges <code>code</code> for a Google access token (form-urlencoded POST to <code>oauth2.googleapis.com/token</code>), and fetches the profile from <code>googleapis.com/oauth2/v2/userinfo</code>.</li><li><code>linkOrCreateUser()</code> links the Google identity to an existing account with the same email (BR-10), or creates a new verified account with no password (BR-11).</li><li>The system checks the account status (BR-06) and, with two-factor authentication disabled (BR-08), sets <code>lastLoginAt</code>, writes an <code>AuditLog</code> (<code>LOGIN</code>), resolves the active workspace, and issues an access token and a refresh token.</li><li>All of the above (account/role/link/audit writes) run inside a single <code>@Transactional</code> method (<code>OAuthService.handleCallback</code>).</li><li><code>GoogleOAuthController</code> sets the refresh token as an <code>HttpOnly</code>/<code>Secure</code>/<code>SameSite=Strict</code> cookie scoped to <code>/api/v1/auth</code>, and 302-redirects to <code>{frontendUrl}/oauth-callback#token={accessToken}</code>.</li><li><code>OAuthCallbackPage</code> / <code>useOAuthCallback()</code> reads the token from the fragment, calls <code>GET /api/v1/auth/me</code>, stores the user/token, shows toast MSG11, and navigates to the pending redirect target or <code>/dashboard</code>.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>4.a1: The user cancels consent or Google returns an error → the callback carries no authorization code; the browser is sent back to <code>oauth-callback?error=oauth_failed</code>, toast MSG12, and no further call to Google is made. 4.a2: The Guest retries &quot;Sign in with Google&quot; from <code>/login</code>.</li><li>5.a1: The state value is missing, already used/expired, or belongs to another provider (BR-09) → 400 <code>OAUTH_STATE_INVALID</code>, browser sent back with toast MSG12. 5.a2: The Guest retries &quot;Sign in with Google&quot; from <code>/login</code>.</li><li>5.b1: The token exchange fails (<code>access_token</code> missing), or the Google profile has no email or an unverified email (BR-10) → 400 <code>OAUTH_CODE_INVALID</code>, browser sent back with toast MSG12. 5.b2: The Guest retries &quot;Sign in with Google&quot; from <code>/login</code>, or signs in with email/password instead.</li><li>5.c1: A <code>RestClientException</code> occurs while calling Google → generic failure redirect, toast MSG12 (no ErrorCode surfaced to the frontend, logged server-side only). 5.c2: The Guest retries.</li><li>7.a1: The account is suspended or deactivated (BR-06) → 403 <code>ACCOUNT_SUSPENDED</code>; <code>businessFailure()</code> redirects to <code>{frontendUrl}/oauth-callback?error=ACCOUNT_SUSPENDED</code>, and the frontend shows a dedicated toast (<code>auth.login.oauthAccountSuspended</code>), distinct from the generic MSG12 OAuth-failure toast. 7.a2: The Guest contacts support to resolve the account status.</li><li>7.b1: Two-factor authentication is enabled on the account (BR-08) → no access token and no refresh token are issued; a two-factor challenge token is returned instead. 7.b2: The browser is sent to <code>{frontendUrl}/2fa-verify?twoFactorToken=...</code> for the Guest to complete sign-in (3.2.7).</li></ul><p>⚠ BA conflict (needs team decision): <code>Section5_Requirement_Appendix.md</code> has no numbered MSG code dedicated to the OAuth <code>ACCOUNT_SUSPENDED</code> toast (BR-06 only defines the generic password-login suspended toast; the appendix&#39;s MSG list stops at MSG14, all OAuth-linking related). The frontend copy for this case lives only as the i18n key <code>auth.login.oauthAccountSuspended</code> (&quot;This account has been suspended. Please contact support.&quot;), not as an appendix MSG-NN entry. Confirm whether this key should be formally registered as a new MSG code in the appendix, or whether ad-hoc i18n keys outside the MSG table are acceptable going forward.</p><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>The Google identity is linked to a local account (<code>UserOAuthProvider</code> row for <code>(GOOGLE, providerId)</code>), created on first use with the email already verified and no password.</li><li>The sign-in is recorded (<code>lastLoginAt</code> updated, <code>AuditLog</code> LOGIN entry written), unless the user still has to complete two-factor verification.</li><li>An access token and a refresh-token cookie are issued, or a two-factor challenge token when two-factor authentication is enabled.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>OAuth provider khác ngoài Google (Facebook, GitHub... không thuộc CSV V2 hiện tại).</li><li>Link-mode (<code>GET /api/v1/auth/oauth/google/link?token=...</code>, a signed-in user attaching Google to their current account) and its <code>OAUTH_EMAIL_MISMATCH</code> / <code>OAUTH_ALREADY_LINKED</code> conflict redirects to <code>/settings</code>.</li><li><code>POST /api/v1/auth/unlink/oauth</code> (body: <code>UnlinkOAuthRequest{provider}</code>) — removing a linked OAuth provider from an account, guarded elsewhere by <code>OAUTH_ONLY_ACCOUNT</code> / <code>LAST_LOGIN_METHOD</code> in <code>AuthController</code>/<code>AuthServiceImpl</code>.</li></ul><h2 id="tham-chieu-ba" tabindex="-1">Tham chiếu BA <a class="header-anchor" href="#tham-chieu-ba" aria-label="Permalink to &quot;Tham chiếu BA&quot;">​</a></h2><p><a href="./../../../BA/02-authentication-profile.html">02-authentication-profile.md</a></p><h2 id="completion-contract-2026-09-19" tabindex="-1">Completion contract (2026-09-19) <a class="header-anchor" href="#completion-contract-2026-09-19" aria-label="Permalink to &quot;Completion contract (2026-09-19)&quot;">​</a></h2><p>Use the configured Google callback URI, including /login/oauth2/code/google. Successful callbacks set an HttpOnly refresh cookie and redirect to the frontend with the access token in the URL fragment. Cancellation, invalid state/code and suspended accounts return a localized frontend error. Only verified Google emails may be linked. Secrets remain in ignored backend environment files. Existing light/dark UI is retained; new error text uses matching vi/en keys.</p>',30)])])}const f=o(c,[["render",n]]);export{g as __pageData,f as default};
